{
  "info": {
    "title": "UAE Payment API",
    "description": "## UAE Open Finance Payment API Specification",
    "version": "v2.1-errata3"
  },
  "servers": [
    {
      "url": "https://rs1.[LFICODE].apihub.openfinance.ae/open-finance/payment/v2.1"
    },
    {
      "url": "https://rs1.[LFICODE].preprod.apihub.openfinance.ae/open-finance/payment/v2.1"
    },
    {
      "url": "https://rs1.altareq1.sandbox.apihub.openfinance.ae/open-finance/payment/v2.1"
    }
  ],
  "source_path": "/payments/{PaymentId}",
  "operations": {
    "get": {
      "tags": [
        "Payment Initiation"
      ],
      "summary": "Retrieve a Payment",
      "description": "Retrieve a Payment\n",
      "operationId": "RetrievePayment",
      "parameters": [
        {
          "$ref": "#/components/parameters/authorization"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id-request"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        },
        {
          "$ref": "#/components/parameters/PaymentId"
        }
      ],
      "responses": {
        "200": {
          "$ref": "#/components/responses/200PaymentId"
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "404": {
          "$ref": "#/components/responses/404Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "415": {
          "$ref": "#/components/responses/415Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "security": [
        {
          "TPPOAuth2Security": [
            "openid",
            "payments"
          ]
        }
      ]
    }
  }
}

{
  "in": "header",
  "name": "authorization",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  },
  "example": "Bearer 12773da5-81c5-45e7-893c-381ca3cecc30"
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the User last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2023 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  },
  "example": "Thu, 26 Jan 2023 16:31:32 UTC"
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  },
  "example": "51.235.115.203"
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  },
  "example": "49df2c2c-6b80-40ee-96a1-71910a248048"
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the User is using.",
  "required": false,
  "schema": {
    "type": "string"
  },
  "example": "Mozilla/5.0 (iPhone; CPU iPhone OS 10_3_1 like Mac OS X) AppleWebKit/603.1.30 (KHTML, like Gecko) Version/10.0 Mobile/14E304 Safari/602.1"
}

{
  "name": "PaymentId",
  "in": "path",
  "description": "Unique identification as assigned by the LFI to uniquely identify the payment resource.",
  "schema": {
    "type": "string",
    "minLength": 1,
    "maxLength": 40
  },
  "required": true,
  "example": "83b47199-90c2-4c05-9ef1-aeae68b0fc7c"
}

{
  "description": "Payment Id",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  },
  "content": {
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEPaymentIdResponseSigned"
      }
    }
  }
}

{
  "required": true,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  },
  "example": "49df2c2c-6b80-40ee-96a1-71910a248048"
}

{
  "description": "Payment Response Signed Schema\n",
  "allOf": [
    {
      "$ref": "#/components/schemas/AEJwt"
    },
    {
      "type": "object",
      "properties": {
        "message": {
          "$ref": "#/components/schemas/AEPaymentIdResponse"
        }
      },
      "required": [
        "message"
      ]
    }
  ]
}

{
  "description": "[https://www.rfc-editor.org/rfc/rfc7519](https://www.rfc-editor.org/rfc/rfc7519)\n",
  "type": "object",
  "properties": {
    "iss": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)\n",
      "type": "string"
    },
    "exp": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)\n",
      "type": "number"
    },
    "nbf": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)\n",
      "type": "number"
    },
    "aud": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)\n",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "iat": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)\n",
      "type": "number"
    }
  },
  "required": [
    "iss",
    "exp",
    "nbf"
  ]
}

{
  "description": "Payment Id Response Schema\n",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Data",
    "Links"
  ],
  "properties": {
    "Data": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "PaymentId",
        "ConsentId",
        "Status",
        "StatusUpdateDateTime",
        "Instruction",
        "CreationDateTime",
        "PaymentPurposeCode",
        "OpenFinanceBilling"
      ],
      "properties": {
        "PaymentId": {
          "$ref": "#/components/schemas/AEPaymentId"
        },
        "ConsentId": {
          "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AEConsentId"
        },
        "PaymentTransactionId": {
          "$ref": "#/components/schemas/AEPaymentTransactionId"
        },
        "Status": {
          "$ref": "#/components/schemas/AEPaymentStatus"
        },
        "StatusUpdateDateTime": {
          "$ref": "#/components/schemas/AEStatusUpdateDateTime"
        },
        "RejectReasonCode": {
          "items": {
            "$ref": "#/components/schemas/AERejectReason"
          },
          "type": "array",
          "minItems": 1
        },
        "CreationDateTime": {
          "$ref": "#/components/schemas/AECreationDateTime"
        },
        "Charges": {
          "$ref": "#/components/schemas/AECharges"
        },
        "ExchangeRate": {
          "$ref": "#/components/schemas/AEExchangeRateInformation"
        },
        "CurrencyRequest": {
          "$ref": "#/components/schemas/AECurrencyRequest"
        },
        "Instruction": {
          "$ref": "#/components/schemas/AEPaymentInstruction"
        },
        "PaymentPurposeCode": {
          "$ref": "#/components/schemas/AEPaymentPurposeCode"
        },
        "DebtorReference": {
          "$ref": "#/components/schemas/AEDebtorReference"
        },
        "OpenFinanceBilling": {
          "$ref": "#/components/schemas/AEServiceInitiationOpenFinancePaymentBilling"
        }
      }
    },
    "Links": {
      "$ref": "#/components/schemas/AELinksRelatedConsent"
    },
    "Meta": {
      "$ref": "#/components/schemas/AEMeta"
    }
  }
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 128,
  "description": "Unique identification assigned by the TPP to identify the consent resource."
}

{
  "description": "Date and time at which the resource status was updated.All dates in the JSON payloads are represented in ISO 8601 date-time format. \nAll date-time fields in responses must include the timezone. An example is below:\n2023-04-05T10:43:07+00:00",
  "type": "string",
  "format": "date-time"
}

{
  "description": "Rejection Reason",
  "type": "object",
  "required": [
    "Code",
    "Message"
  ],
  "additionalProperties": false,
  "properties": {
    "Code": {
      "description": "Rejected Reason Code is a namespaced rejection reason code. The first part of the code is the namespace, which is the name of the organisation or system (e.g., AANI) that is rejecting the payment, and the second part is the specific rejection reason code for the originating organisation or system.\nPayments that are rejected by AANI will have the AANI prefix, followed by the specific ANNI reason code.\n\nThe Payment resouce is updated with the rejection reason code if a Rejected payment is initially created in a Pending state. \nIf the Payment resource is rejected, and no Payment resource is created - a 4xx HTTP status code is returned to the TPP with the appropriate Error Response.\n",
      "type": "string",
      "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
    },
    "Message": {
      "$ref": "#/components/schemas/AEMessage"
    }
  }
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 500,
  "description": "A description of the error that occurred. e.g., 'A mandatory field isn't supplied' or 'RequestedExecutionDateTime must be in future'\nThis field is not standardised"
}

{
  "description": "Date and time at which the message was created. All dates in the JSON payloads are represented in ISO 8601 date-time format. \nAll date-time fields in responses must include the timezone. An example is below:\n2023-04-05T10:43:07+00:00",
  "type": "string",
  "format": "date-time"
}

{
  "type": "array",
  "items": {
    "type": "object",
    "additionalProperties": false,
    "description": "Set of elements used to provide details of a charge for the payment initiation.\n* For Payments, these Charges are on the Debtor.\n",
    "required": [
      "ChargeBearer",
      "Type",
      "Amount"
    ],
    "properties": {
      "ChargeBearer": {
        "$ref": "#/components/schemas/AEChargeBearerType1Code"
      },
      "Type": {
        "$ref": "#/components/schemas/AEExternalPaymentChargeTypeCode"
      },
      "Amount": {
        "$ref": "#/components/schemas/AEActiveCurrencyAmount"
      }
    }
  }
}

{
  "description": "Specifies which party/parties will bear the charges associated with the processing of the payment transaction.",
  "type": "string",
  "enum": [
    "BorneByCreditor",
    "BorneByDebtor",
    "Shared"
  ]
}

{
  "description": "Charge type, in a coded form.",
  "type": "string",
  "enum": [
    "VAT",
    "Fees"
  ]
}

{
  "description": "The Currency and Amount relating to the Payment\n",
  "type": "object",
  "required": [
    "Amount",
    "Currency"
  ],
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveOrHistoricAmount"
    },
    "Currency": {
      "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyCode"
    }
  }
}

{
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "type": "string",
  "pattern": "^\\d{1,16}\\.\\d{2}$",
  "example": "100.00"
}

{
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "example": "AED"
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "UnitCurrency",
    "ExchangeRate",
    "RateType"
  ],
  "description": "Further detailed information on the exchange rate that has been used in the payment transaction - returned by the LFI.",
  "properties": {
    "UnitCurrency": {
      "description": "Currency in which the rate of exchange is expressed in a currency exchange. In the example 1GBP = xxxCUR, the unit currency is GBP.",
      "type": "string",
      "pattern": "^[A-Z]{3,3}$"
    },
    "ExchangeRate": {
      "description": "The factor used for conversion of an amount from one currency to another. This reflects the price at which one currency was bought with another currency.",
      "type": "number"
    },
    "RateType": {
      "description": "Specifies the type used to complete the currency exchange.",
      "type": "string",
      "enum": [
        "Actual",
        "Agreed",
        "Indicative"
      ]
    },
    "ContractIdentification": {
      "description": "Unique and unambiguous reference to the foreign exchange contract agreed between the initiating party/creditor and the debtor agent.",
      "type": "string",
      "minLength": 1,
      "maxLength": 256
    },
    "ExpirationDateTime": {
      "description": "Specified date and time the exchange rate agreement will expire. All dates in the JSON payloads are represented in ISO 8601 date-time format. \nAll date-time fields in responses must include the timezone. An example is below:\n2017-04-05T10:43:07+00:00",
      "type": "string",
      "format": "date-time"
    }
  }
}

{
  "description": "The details of the non-local currency or FX request that has been agreed between the User and the TPP.\nThe requested ChargeBearer and ExchangeRateInformation are included in this object may be overwritten by the LFI in the returned Consent object.\n",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "ExtendedPurpose",
    "CurrencyOfTransfer"
  ],
  "properties": {
    "InstructionPriority": {
      "description": "Indicator of the urgency or order of importance that the instructing party would like the instructed party to apply to the processing of the instruction.",
      "type": "string",
      "enum": [
        "Normal",
        "Urgent"
      ]
    },
    "ExtendedPurpose": {
      "description": "Specifies the purpose of an international payment.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "ChargeBearer": {
      "$ref": "#/components/schemas/AEChargeBearerType1Code"
    },
    "CurrencyOfTransfer": {
      "description": "Specifies the currency of the to be transferred amount, which is different from the currency of the debtor's account.",
      "type": "string",
      "pattern": "^[A-Z]{3,3}$"
    },
    "DestinationCountryCode": {
      "description": "Country in which Credit Account is domiciled. Code to identify a country, a dependency, or another area of particular geopolitical interest, on the basis of country names obtained from the United Nations (ISO 3166, Alpha-2 code).",
      "type": "string",
      "pattern": "[A-Z]{2,2}"
    },
    "ExchangeRateInformation": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "UnitCurrency",
        "RateType"
      ],
      "description": "Provides details on the currency exchange rate and contract.",
      "properties": {
        "UnitCurrency": {
          "description": "Currency in which the rate of exchange is expressed in a currency exchange. In the example 1GBP = xxxCUR, the unit currency is GBP.",
          "type": "string",
          "pattern": "^[A-Z]{3,3}$"
        },
        "ExchangeRate": {
          "description": "The factor used for conversion of an amount from one currency to another. This reflects the price at which one currency was bought with another currency.",
          "type": "number"
        },
        "RateType": {
          "description": "Specifies the type used to complete the currency exchange.",
          "type": "string",
          "enum": [
            "Actual",
            "Agreed",
            "Indicative"
          ]
        },
        "ContractIdentification": {
          "description": "Unique and unambiguous reference to the foreign exchange contract agreed between the initiating party/creditor and the debtor agent.",
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        }
      }
    },
    "FxQuoteId": {
      "description": "Required where the consent or payment initiation request relates to a previously quoted FX trade. The TPP must provide the `QuoteId` value where a long-lived consent exists, meaning that each payment initiation request will relate to a different `QuoteId` value.",
      "type": "string",
      "minLength": 1,
      "maxLength": 128
    }
  }
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Amount"
  ],
  "description": "The Initiation payload is sent by the initiating party to the LFI. It is used to request movement of funds from the debtor account to a creditor for a single payment.",
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveCurrencyAmount"
    }
  }
}

{
  "type": "object",
  "required": [
    "Type"
  ],
  "properties": {
    "Type": {
      "enum": [
        "Collection",
        "LargeValueCollection",
        "PushP2P",
        "PullP2P",
        "Me2Me"
      ],
      "description": "The type payment for billing",
      "type": "string"
    },
    "MerchantId": {
      "description": "MerchantId",
      "type": "string",
      "minLength": 8,
      "maxLength": 20
    }
  },
  "description": "Billing parameters specified by the TPP for a payment initiation",
  "additionalProperties": false
}

{
  "type": "object",
  "description": "Links relevant to the resource",
  "required": [
    "Self",
    "Related"
  ],
  "properties": {
    "Self": {
      "$ref": "#/components/schemas/AERelatedSinglePayment"
    },
    "Related": {
      "$ref": "#/components/schemas/AESelfConsent"
    }
  },
  "additionalProperties": false
}

{
  "type": "string",
  "format": "uri",
  "description": "A link to the current payment resource",
  "example": "https://api.lfi.sa/open-banking/payment/2023.11.01-final/payments/83b47199-90c2-4c05-9ef1-aeae68b0fc7c"
}

{
  "description": "A link to the related payment consents resource",
  "type": "string",
  "format": "uri",
  "example": "https://api.lfi.sa/open-banking/payment/2023.11.01-final/payment-consents/aac-69255d98-ab0e-4758-92a7-cacbf3073efa"
}

{
  "type": "object",
  "description": "Meta Data relevant to the resource",
  "additionalProperties": false
}

{
  "description": "Bad request",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  },
  "content": {
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEError400ResponseSigned"
      },
      "examples": {
        "Bad Request": {
          "$ref": "#/components/examples/Error400BadRequestSigned"
        }
      }
    }
  }
}

{
  "description": "Error Signed Schema\n",
  "allOf": [
    {
      "$ref": "#/components/schemas/AEJwt"
    },
    {
      "type": "object",
      "properties": {
        "message": {
          "$ref": "#/components/schemas/AEError400Response"
        }
      },
      "required": [
        "message"
      ]
    }
  ]
}

{
  "description": "An array of detail error codes, and messages, and URLs to documentation to help remediation.",
  "type": "object",
  "properties": {
    "Errors": {
      "items": {
        "$ref": "#/components/schemas/AEError400"
      },
      "type": "array",
      "minItems": 1
    }
  },
  "required": [
    "Errors"
  ],
  "additionalProperties": false
}

{
  "description": "Error",
  "type": "object",
  "required": [
    "Code",
    "Message"
  ],
  "additionalProperties": false,
  "properties": {
    "Code": {
      "$ref": "#/components/schemas/AEError400Code"
    },
    "Message": {
      "$ref": "#/components/schemas/AEMessage"
    },
    "Path": {
      "description": "Recommended but optional reference to the JSON Path of the field with error, e.g., Data.Initiation.InstructedAmount.Currency",
      "type": "string",
      "minLength": 1,
      "maxLength": 500
    },
    "Url": {
      "description": "URL to help remediate the problem, or provide more information, or to API Reference, or help etc",
      "type": "string"
    }
  }
}

{
  "summary": "400 Bad Request",
  "description": "400 Bad Request",
  "value": {
    "iss": "c50f0152-49bb-4dc4-b866-b625271c4e78",
    "exp": 3349494246,
    "nbf": 1675765189,
    "aud": [
      "e63df191-5fff-4e9c-bba2-b273c94e87f0"
    ],
    "iat": 1675765189,
    "message": {
      "Errors": [
        {
          "Code": "GenericError",
          "Message": "A mandatory field is missing."
        }
      ]
    }
  }
}

{
  "description": "Unauthorized",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  }
}

{
  "description": "Forbidden",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  },
  "content": {
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEError403ResponseSigned"
      },
      "examples": {
        "Forbidden": {
          "$ref": "#/components/examples/Error403ForbiddenSigned"
        }
      }
    }
  }
}

{
  "description": "Error Signed Schema\n",
  "allOf": [
    {
      "$ref": "#/components/schemas/AEJwt"
    },
    {
      "type": "object",
      "properties": {
        "message": {
          "$ref": "#/components/schemas/AEError403Response"
        }
      },
      "required": [
        "message"
      ]
    }
  ]
}

{
  "description": "An array of detail error codes, and messages, and URLs to documentation to help remediation.",
  "type": "object",
  "properties": {
    "Errors": {
      "items": {
        "$ref": "#/components/schemas/AEError403"
      },
      "type": "array",
      "minItems": 1
    }
  },
  "required": [
    "Errors"
  ],
  "additionalProperties": false
}

{
  "description": "Error",
  "type": "object",
  "required": [
    "Code",
    "Message"
  ],
  "additionalProperties": false,
  "properties": {
    "Code": {
      "$ref": "#/components/schemas/AEError403Code"
    },
    "Message": {
      "$ref": "#/components/schemas/AEMessage"
